body {
    font-family: Tahoma, sans-serif;
    font-sizq: 1rem;
}
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
}
.pth, td {
    border: 1px solid black;
    padding: 5px !important;
    text-align: left;
    color: black !important;
}
.pth {
    color: black !important;
    font-weight: bold!important;
    width: 40%;
}

.percent-col {
    width: 5% !important;
    text-align: right;
}

.amount-col {
    width: 55% !important;
}

.full-col {
    width: 60% !important;
}
